/** * Ambient declaration for `@earendil-works/pi-coding-agent` — the pi extension * API. pi ships its types from a `dist/index.d.ts` that is not present in this * install, and the package lives under the ~/.pi tree (not in this repo), so * the repo carries a minimal mirror of the surface the extension uses. * * Verified surface (probes, pi 0.85.1): * - `pi.registerTool`, `pi.on`, `pi.getActiveTools()`, `pi.getAllTools()`, * `pi.setActiveTools()`. The introspection/action methods throw * "Extension runtime not initialized. Action methods cannot be called * during extension loading." — use them at session_start or later * (verified 2026-07-15 against the installed 0.85.1 binary). * - `getAllTools()` returns one metadata object per registered tool name — * `{ name, description, parameters, promptGuidelines, sourceInfo }`. * pi merges all extensions' tools into a name-keyed map (last-loaded * wins), so a name never appears twice; conflicts are detected via * `sourceInfo.path`. * - tool `execute(toolCallId, params, signal, onUpdate, ctx)`: the `signal` is * the agent's AbortSignal (probed: it flips on turn abort; the tool's * cleanup runs and its return value lands as a normal tool result), * `onUpdate({content, details})` streams partial results to the TUI. * - `execute` must resolve to a `ToolResult` object (`{ content, details? }`), * never a plain string (upstream type: `AgentToolResult`). A string result * crashes the pi process in TUI mode — `getTextOutput` dereferences * `result.content` unconditionally (uncaught TypeError at * `tool_execution_end`) — and the session record silently stores * `content: []`, dropping the text. Verified 2026-09-17: the first TUI * smoke dispatch killed both the worker tile (on `vitrine_done`) and the * dispatcher window (on `vitrine_dispatch`) this way; headless `--print` * mode has no TUI display path, so it never surfaced in the earlier * bring-up. Tool errors are signalled by throwing — pi wraps the thrown * error into an error tool result (`isError: true`); `AgentToolResult` * carries no `isError` field. `terminate: true` stops the agent after the * batch only when every result in the batch sets it. * - `ctx.sessionManager.getSessionId()` / `.getSessionFile()`, `ctx.model`, * `ctx.cwd`, `ctx.isProjectTrusted`, `ctx.ui.notify`. * - tool `parameters` must be a typebox `Type.Object` — a raw `{}` silently * registers a tool with no schema (probe). `typebox` is provided to * extensions by pi. * - tool custom rendering (verified 2026-09-18 against the installed 0.85.1 * docs "Custom Rendering" + examples/extensions/built-in-tool-renderer.ts): * `renderCall(args, theme, context)` / `renderResult(result, { expanded, * isPartial }, theme, context)` on a tool definition return a pi-tui * component (`Text` / `Container` / `Markdown`); `expanded` is the user's * output toggle (ctrl+e / click); `renderShell: "self"` opts out of the * default Box. `getMarkdownTheme()` (this package) feeds the `Markdown` * component. TUI mode only — headless `--print` never calls the renderers, * but their imports load in every mode (jiti). * Keep it in sync with the installed pi when you extend it. */
declare module "@earendil-works/pi-coding-agent" { export interface ToolContentText { type: "text"; text: string; } /** * Final or partial result a tool's `execute` must resolve to (upstream * `AgentToolResult`). `content` is mandatory — pi's TUI dereferences * `result.content` unconditionally, and the session record derives its * content from it (`result.content ?? []`): a non-object result (e.g. a * plain string) crashes the TUI and is silently dropped from the record. */ export interface ToolResult<T = unknown> { content: ToolContentText[]; details?: T; /** Stop after this tool batch only if every result in the batch sets it. */ terminate?: boolean; } export interface ToolUpdate { content: ToolContentText[]; details?: unknown; } /** A pi-tui component — the minimal surface a tool renderer returns * (structural: any object with `render` is a component). */ export interface TuiComponent { render(width: number): string[]; dispose?(): void; } /** The slice of the TUI theme a tool renderer receives (the upstream * `Theme` structurally satisfies it). */ export interface RenderTheme { fg(color: string, text: string): string; bold(text: string): string; } /** A tool row's output state (upstream renderResult options object). */ export interface ToolRenderOptions { /** The user toggled the output open (ctrl+e / click). */ expanded: boolean; /** A partial result is streaming (`onUpdate`). */ isPartial: boolean; } /** The tool result as handed to renderResult (the record's ToolResultMessage). */ export interface RenderedToolResult { content: ToolContentText[]; details?: unknown; isError?: boolean; } /** A tool renderer's row-local context (upstream `ToolRenderContext`; * the fields the renderers may read). */ export interface ToolRenderContext { args: Record<string, unknown>; toolCallId: string; expanded: boolean; isPartial: boolean; state: Record<string, unknown>; invalidate(): void; } /** The markdown theme for pi-tui `Markdown` (opaque — the component consumes it). */ export interface MarkdownTheme { /* opaque */ } /** The active markdown theme (feeds the pi-tui `Markdown` component). */ export function getMarkdownTheme(): MarkdownTheme; export interface SessionManager { getSessionId(): string; getSessionFile(): string; } export interface ExtensionUI { /** `kind`: "info" | "warning" | "error" (pi's notify kinds). */ notify(kind: string, message: string): void; } /** The context pi hands a tool's execute (the fields Vitrine uses). */ export interface ExtensionToolContext { sessionManager: SessionManager; /** The session's current model (nullable). */ model: unknown; /** The session's cwd. */ cwd: string; /** Project trust — gates project-local agent lookup. */ isProjectTrusted: boolean; ui: ExtensionUI; } export interface ToolDefinition { name: string; label?: string; description?: string; /** A typebox `Type.Object` (pi provides `typebox`). */ parameters?: unknown; execute?: ( toolCallId: string, params: Record<string, unknown>, signal: AbortSignal, onUpdate?: (update: ToolUpdate) => void, ctx?: ExtensionToolContext, ) => ToolResult | Promise<ToolResult>; /** Custom TUI rendering of the tool-call row (TUI mode only). */ renderCall?: (args: Record<string, unknown>, theme: RenderTheme, context: ToolRenderContext) => TuiComponent; /** Custom TUI rendering of the tool-result row (TUI mode only). */ renderResult?: ( result: RenderedToolResult, options: ToolRenderOptions, theme: RenderTheme, context: ToolRenderContext, ) => TuiComponent; /** Render the row's own shell instead of the default Box. */ renderShell?: "self"; } /** Where a tool was registered from (the entry file, absolute). */ export interface ToolSourceInfo { path: string; source?: string; scope?: string; origin?: string; } /** One entry of `getAllTools()`. */ export interface ToolInfo { name: string; description?: string; parameters?: unknown; promptGuidelines?: unknown; sourceInfo: ToolSourceInfo; } export interface ExtensionAPI { registerTool(def: ToolDefinition): void; on(event: string, handler: (...args: never[]) => unknown): void; /** Names of the tools active for the session. */ getActiveTools(): string[]; /** All registered tools, with their registration source. */ getAllTools(): ToolInfo[]; /** Replace the session's active tool set (session_start or later). */ setActiveTools(toolNames: string[]): void; /** The session's name (`pi --name`). */ getSessionName(): string | undefined; }
} 